async ({ shell: { execFile }, workspace: { edit } }) => {
  const v = await execFile("gh", ["pr", "view", "76", "--json", "body", "-q", ".body"]);
  const raw = v.stdout.replace(/\n$/, "");
  const body: string = JSON.parse(raw);
  await edit("/tmp/pr76.md", { revision: null, changes: [{ kind: "replaceFile", content: body }] });
  const e = await execFile("gh", ["pr", "edit", "76", "--body-file", "/tmp/pr76.md"]);
  const after = await execFile("gh", ["pr", "view", "76", "--json", "body", "-q", ".body"]);
  return { code: e.code, err: e.stderr, head: after.stdout.slice(0, 300), hasLiteralNL: after.stdout.includes("\\n") };
}
